insert into app_private.starter_content values('2026-11','ingredient','lentils_red','{"id": "lentils_red", "name": {"en": "Red split lentils, dry", "es": "Lentejas rojas partidas, secas"}, "state": "dry", "quantity_basis": "edible_reference_weight", "food_class": "plant", "variety_key": "lentil", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "nutrition_per_100g": {"energy_kcal": 311.0, "protein_g": 25.6, "fat_g": 1.8, "carbohydrate_g": 51.2, "fibre_aoac_g": 17.4}, "conversions": [{"unit": "g", "grams_per_unit": 1, "basis": "mass_definition"}, {"unit": "kg", "grams_per_unit": 1000, "basis": "mass_definition"}], "default_unit": "g", "source": {"dataset": "cofid_2021", "food_code": "13-657", "original_name": "Lentils, red, split, dried, raw", "proximates_row": 1555, "factors_row": 1555, "energy_cell": "M1555", "raw_energy_value": "311"}, "shopping_policy": "include", "preparation": {"kind": "dry_lentil", "soak_minutes": 0, "additional_cook_minutes_range": [20, 40], "instructions": {"en": "Weigh dry and rinse. Cook in plenty of water until fully tender, following the packet; red split lentils usually soften sooner than whole lentils. No cooked-weight conversion is assumed.", "es": "Pesa en seco y enjuaga. Cuece en abundante agua hasta que estén completamente tiernas, siguiendo el envase; las lentejas rojas partidas suelen ablandarse antes que las enteras. No se presupone ninguna conversión de peso cocido."}}}'::jsonb);
insert into app_private.starter_content values('2026-11','ingredient','lentils_green','{"id": "lentils_green", "name": {"en": "Green/brown lentils, dry", "es": "Lentejas verdes o pardinas, secas"}, "state": "dry", "quantity_basis": "edible_reference_weight", "food_class": "plant", "variety_key": "lentil", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "nutrition_per_100g": {"energy_kcal": 297.0, "protein_g": 24.3, "fat_g": 1.9, "carbohydrate_g": 48.8, "fibre_aoac_g": null}, "conversions": [{"unit": "g", "grams_per_unit": 1, "basis": "mass_definition"}, {"unit": "kg", "grams_per_unit": 1000, "basis": "mass_definition"}], "default_unit": "g", "source": {"dataset": "cofid_2021", "food_code": "13-089", "original_name": "Lentils, green and brown, whole, dried, raw", "proximates_row": 1553, "factors_row": 1553, "energy_cell": "M1553", "raw_energy_value": "297"}, "shopping_policy": "include", "preparation": {"kind": "dry_lentil", "soak_minutes": 0, "additional_cook_minutes_range": [20, 40], "instructions": {"en": "Weigh dry and rinse. Cook in plenty of water until fully tender, following the packet; red split lentils usually soften sooner than whole lentils. No cooked-weight conversion is assumed.", "es": "Pesa en seco y enjuaga. Cuece en abundante agua hasta que estén completamente tiernas, siguiendo el envase; las lentejas rojas partidas suelen ablandarse antes que las enteras. No se presupone ninguna conversión de peso cocido."}}}'::jsonb);
insert into app_private.starter_content values('2026-11','ingredient','chickpeas','{"id": "chickpeas", "name": {"en": "Whole chickpeas, dry", "es": "Garbanzos enteros secos"}, "state": "dry", "quantity_basis": "edible_reference_weight", "food_class": "plant", "variety_key": "chickpea", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "nutrition_per_100g": {"energy_kcal": 320.0, "protein_g": 21.3, "fat_g": 5.4, "carbohydrate_g": 49.6, "fibre_aoac_g": null}, "conversions": [{"unit": "g", "grams_per_unit": 1, "basis": "mass_definition"}, {"unit": "kg", "grams_per_unit": 1000, "basis": "mass_definition"}], "default_unit": "g", "source": {"dataset": "cofid_2021", "food_code": "13-074", "original_name": "Beans, chick peas, Kabuli, whole, dried, raw", "proximates_row": 140, "factors_row": 140, "energy_cell": "M140", "raw_energy_value": "320"}, "shopping_policy": "include", "preparation": {"kind": "dry_legume", "soak_minutes": 720, "additional_cook_minutes_range": [60, 120], "instructions": {"en": "Weigh dry, then soak at least 12 hours. Discard soaking water, rinse, and use plenty of fresh water. Boil vigorously for at least 10 minutes, then continue cooking until fully tender, following the packet if it requires longer. Never cook raw kidney beans only in a slow cooker. The dry weight, not the hydrated weight, is the calorie reference.", "es": "Pesa en seco y remoja al menos 12 horas. Desecha el agua de remojo, enjuaga y usa abundante agua nueva. Hierve enérgicamente al menos 10 minutos y continúa la cocción hasta que estén completamente tiernas, siguiendo el envase si exige más tiempo. Nunca cocines alubias rojas crudas solo en una olla de cocción lenta. La referencia calórica es el peso seco, no el hidratado."}}}'::jsonb);
insert into app_private.starter_content values('2026-11','ingredient','beans_white','{"id": "beans_white", "name": {"en": "Haricot beans, dry", "es": "Alubias blancas secas"}, "state": "dry", "quantity_basis": "edible_reference_weight", "food_class": "plant", "variety_key": "white_bean", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "nutrition_per_100g": {"energy_kcal": 286.0, "protein_g": 21.4, "fat_g": 1.6, "carbohydrate_g": 49.7, "fibre_aoac_g": null}, "conversions": [{"unit": "g", "grams_per_unit": 1, "basis": "mass_definition"}, {"unit": "kg", "grams_per_unit": 1000, "basis": "mass_definition"}], "default_unit": "g", "source": {"dataset": "cofid_2021", "food_code": "13-086", "original_name": "Beans, haricot, whole, dried, raw", "proximates_row": 147, "factors_row": 147, "energy_cell": "M147", "raw_energy_value": "286"}, "shopping_policy": "include", "preparation": {"kind": "dry_legume", "soak_minutes": 720, "additional_cook_minutes_range": [60, 120], "instructions": {"en": "Weigh dry, then soak at least 12 hours. Discard soaking water, rinse, and use plenty of fresh water. Boil vigorously for at least 10 minutes, then continue cooking until fully tender, following the packet if it requires longer. Never cook raw kidney beans only in a slow cooker. The dry weight, not the hydrated weight, is the calorie reference.", "es": "Pesa en seco y remoja al menos 12 horas. Desecha el agua de remojo, enjuaga y usa abundante agua nueva. Hierve enérgicamente al menos 10 minutos y continúa la cocción hasta que estén completamente tiernas, siguiendo el envase si exige más tiempo. Nunca cocines alubias rojas crudas solo en una olla de cocción lenta. La referencia calórica es el peso seco, no el hidratado."}}}'::jsonb);
insert into app_private.starter_content values('2026-11','ingredient','beans_kidney','{"id": "beans_kidney", "name": {"en": "Red kidney beans, dry", "es": "Alubias rojas secas"}, "state": "dry", "quantity_basis": "edible_reference_weight", "food_class": "plant", "variety_key": "kidney_bean", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "nutrition_per_100g": {"energy_kcal": 266.0, "protein_g": 22.1, "fat_g": 1.4, "carbohydrate_g": 44.1, "fibre_aoac_g": null}, "conversions": [{"unit": "g", "grams_per_unit": 1, "basis": "mass_definition"}, {"unit": "kg", "grams_per_unit": 1000, "basis": "mass_definition"}], "default_unit": "g", "source": {"dataset": "cofid_2021", "food_code": "13-109", "original_name": "Beans, red kidney, dried, raw", "proximates_row": 162, "factors_row": 162, "energy_cell": "M162", "raw_energy_value": "266"}, "shopping_policy": "include", "preparation": {"kind": "dry_legume", "soak_minutes": 720, "additional_cook_minutes_range": [60, 120], "instructions": {"en": "Weigh dry, then soak at least 12 hours. Discard soaking water, rinse, and use plenty of fresh water. Boil vigorously for at least 10 minutes, then continue cooking until fully tender, following the packet if it requires longer. Never cook raw kidney beans only in a slow cooker. The dry weight, not the hydrated weight, is the calorie reference.", "es": "Pesa en seco y remoja al menos 12 horas. Desecha el agua de remojo, enjuaga y usa abundante agua nueva. Hierve enérgicamente al menos 10 minutos y continúa la cocción hasta que estén completamente tiernas, siguiendo el envase si exige más tiempo. Nunca cocines alubias rojas crudas solo en una olla de cocción lenta. La referencia calórica es el peso seco, no el hidratado."}}}'::jsonb);
insert into app_private.starter_content values('2026-11','ingredient','beans_blackeye','{"id": "beans_blackeye", "name": {"en": "Black-eyed beans, dry", "es": "Alubias carillas secas"}, "state": "dry", "quantity_basis": "edible_reference_weight", "food_class": "plant", "variety_key": "blackeye_bean", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "nutrition_per_100g": {"energy_kcal": 311.0, "protein_g": 23.5, "fat_g": 1.6, "carbohydrate_g": 54.1, "fibre_aoac_g": null}, "conversions": [{"unit": "g", "grams_per_unit": 1, "basis": "mass_definition"}, {"unit": "kg", "grams_per_unit": 1000, "basis": "mass_definition"}], "default_unit": "g", "source": {"dataset": "cofid_2021", "food_code": "13-062", "original_name": "Beans, blackeye, whole, dried, raw", "proximates_row": 128, "factors_row": 128, "energy_cell": "M128", "raw_energy_value": "311"}, "shopping_policy": "include", "preparation": {"kind": "dry_legume", "soak_minutes": 720, "additional_cook_minutes_range": [60, 120], "instructions": {"en": "Weigh dry, then soak at least 12 hours. Discard soaking water, rinse, and use plenty of fresh water. Boil vigorously for at least 10 minutes, then continue cooking until fully tender, following the packet if it requires longer. Never cook raw kidney beans only in a slow cooker. The dry weight, not the hydrated weight, is the calorie reference.", "es": "Pesa en seco y remoja al menos 12 horas. Desecha el agua de remojo, enjuaga y usa abundante agua nueva. Hierve enérgicamente al menos 10 minutos y continúa la cocción hasta que estén completamente tiernas, siguiendo el envase si exige más tiempo. Nunca cocines alubias rojas crudas solo en una olla de cocción lenta. La referencia calórica es el peso seco, no el hidratado."}}}'::jsonb);
insert into app_private.starter_content values('2026-11','ingredient','tofu','{"id": "tofu", "name": {"en": "Plain steamed tofu (source-specific)", "es": "Tofu natural al vapor (referencia específica)"}, "state": "steamed_ready_to_use", "quantity_basis": "edible_reference_weight", "food_class": "plant", "variety_key": "tofu", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "nutrition_per_100g": {"energy_kcal": 73.0, "protein_g": 8.1, "fat_g": 4.2, "carbohydrate_g": 0.7, "fibre_aoac_g": null}, "conversions": [{"unit": "g", "grams_per_unit": 1, "basis": "mass_definition"}, {"unit": "kg", "grams_per_unit": 1000, "basis": "mass_definition"}], "default_unit": "g", "source": {"dataset": "cofid_2021", "food_code": "13-570", "original_name": "Tofu, soya bean, steamed", "proximates_row": 2719, "factors_row": 2719, "energy_cell": "M2719", "raw_energy_value": "73"}, "shopping_policy": "include", "preparation": null, "source_match_note": {"en": "The source describes plain STEAMED tofu (73 kcal/100 g), not every firm tofu brand. Use a matching product or replace its nutrition values before planning.", "es": "La referencia describe tofu natural AL VAPOR (73 kcal/100 g), no cualquier tofu firme comercial. Usa un producto equivalente o actualiza sus valores antes de planificar."}, "dietary_label_condition": {"for_patterns": ["vegan"], "status": "requires_actual_product_label_confirmation", "requirement": {"en": "Choose a source-matching product whose label confirms the selected dietary pattern; generic nutrition data do not certify every brand.", "es": "Elige un producto que corresponda a la referencia y cuya etiqueta confirme el patrón alimentario elegido; los datos genéricos no certifican todas las marcas."}}}'::jsonb);
