insert into app_private.starter_content values('2026-11','recipe','b01','{"id": "b01", "name": {"en": "Apple and ginger porridge", "es": "Gachas de avena con manzana y jengibre"}, "meal_types": ["breakfast"], "reference_servings": 1, "active_prep_minutes": 5, "finishing_cook_minutes": 8, "components": [{"id": "main", "kind": "main", "name": {"en": "Apple and ginger porridge", "es": "Gachas de avena con manzana y jengibre"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "oats", "quantity": 50, "unit": "g", "variety_role": "base"}, {"ingredient_id": "milk", "quantity": 200, "unit": "g", "variety_role": "support"}, {"ingredient_id": "apple", "quantity": 120, "unit": "g", "variety_role": "support"}, {"ingredient_id": "ginger", "quantity": 2, "unit": "g", "variety_role": "support"}, {"ingredient_id": "walnut", "quantity": 10, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Core and dice the apple; grate the ginger.", "es": "Retira el corazón de la manzana, córtala y ralla el jengibre."}, {"en": "Simmer the oats, milk, apple and ginger gently for 5–8 minutes, stirring; add a little water if needed.", "es": "Cuece suavemente la avena, la leche, la manzana y el jengibre durante 5–8 minutos, removiendo; añade un poco de agua si hace falta."}, {"en": "Serve with the measured chopped walnuts.", "es": "Sirve con las nueces pesadas y troceadas."}], "reference_energy_kcal": 413.38, "reference_energy_kcal_exact": "413.38", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian"], "variety_keys": ["oats"]}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 413.38, "with_optional_dessert": 413.38}, "reference_energy_kcal_exact": {"without_optional_dessert": "413.38", "with_optional_dessert": "413.38"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian", "vegetar