insert into app_private.starter_content values('2026-11','recipe','b12','{"id": "b12", "name": {"en": "Chickpea and tomato toast", "es": "Tostada de garbanzos y tomate"}, "meal_types": ["breakfast"], "reference_servings": 1, "active_prep_minutes": 8, "finishing_cook_minutes": 3, "components": [{"id": "main", "kind": "main", "name": {"en": "Chickpea and tomato toast", "es": "Tostada de garbanzos y tomate"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "chickpeas", "quantity": 40, "unit": "g", "variety_role": "main"}, {"ingredient_id": "bread", "quantity": 60, "unit": "g", "variety_role": "base"}, {"ingredient_id": "tomato", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 10, "unit": "g", "variety_role": "support"}, {"ingredient_id": "parsley", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Prepare the chickpeas from their weighed dry amount using the separate soaking and boiling instructions.", "es": "Prepara los garbanzos a partir de su peso en seco siguiendo las instrucciones separadas de remojo y cocción."}, {"en": "Mash the cooked chickpeas with lemon, salt and measured oil. Spread onto toast and add tomato and parsley.", "es": "Machaca los garbanzos cocidos con el limón, la sal y el aceite medido. Extiende sobre la tostada y añade tomate y perejil."}], "reference_energy_kcal": 318.87, "reference_energy_kcal_exact": "318.87", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["bread", "chickpea"]}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 318.87, "with_optional_dessert": 318.87}, "referenc