nd.", "es": "Elige un producto que corresponda a la referencia y cuya etiqueta confirme el patrón alimentario elegido; los datos genéricos no certifican todas las marcas."}}]}, "finishing_times_exclude_soaking_and_prerequisite_cooking": true, "safety_note_ids": ["weigh_and_prepare"]}'::jsonb);
insert into app_private.starter_content values('2026-11','recipe','m01','{"id": "m01", "name": {"en": "Chickpea and spinach tomato stew", "es": "Guiso de garbanzos con tomate y espinacas"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 20, "components": [{"id": "main", "kind": "main", "name": {"en": "Chickpea and spinach tomato stew", "es": "Guiso de garbanzos con tomate y espinacas"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "chickpeas", "quantity": 60, "unit": "g", "variety_role": "main"}, {"ingredient_id": "spinach", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "tomato_canned", "quantity": 200, "unit": "g", "variety_role": "support"}, {"ingredient_id": "onion", "quantity": 60, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Prepare the dry chickpeas separately. Soften the chopped onion and garlic in the measured oil.", "es": "Prepara aparte los garbanzos secos. Rehoga la cebolla y el ajo picados con el aceite medido."}, {"en": "Add tomatoes and simmer 10 minutes. Add the cooked chickpeas, then spinach; cook until the spinach is tender.", "es": "Añade el tomate y cuece 10 minutos. Incorpora los garbanzos cocidos y después las espinacas; cocina hasta que estén tiernas."}], "reference_energy_kcal": 314.89, "reference_energy_kcal_exact": "314.89", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["chickpea"]}, {"id": "side", "kind": "side", "name": {"en": "Grain accompaniment", "es": "Guarnición de cereal"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "rice_brown", "quantity": 50, "unit": "g", 