insert into app_private.starter_content values('2026-11','recipe','m09','{"id": "m09", "name": {"en": "Chickpea and aubergine ginger curry", "es": "Garbanzos con berenjena y jengibre"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 30, "components": [{"id": "main", "kind": "main", "name": {"en": "Chickpea and aubergine ginger curry", "es": "Garbanzos con berenjena y jengibre"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "chickpeas", "quantity": 60, "unit": "g", "variety_role": "main"}, {"ingredient_id": "aubergine", "quantity": 180, "unit": "g", "variety_role": "support"}, {"ingredient_id": "tomato_canned", "quantity": 150, "unit": "g", "variety_role": "support"}, {"ingredient_id": "coconut_milk", "quantity": 60, "unit": "g", "variety_role": "support"}, {"ingredient_id": "ginger", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "chilli", "quantity": 2, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Prepare the dry chickpeas separately. Dice aubergine and cook in measured oil, adding splashes of water rather than extra oil.", "es": "Prepara aparte los garbanzos secos. Corta la berenjena y cocínala con el aceite medido, añadiendo pequeñas cantidades de agua en vez de más aceite."}, {"en": "Add ginger, garlic, chilli, tomatoes and coconut milk. Simmer until the aubergine is tender; add cooked chickpeas and heat through.", "es": "Añade el jengibre, el ajo, la guindilla, el tomate y la leche de coco. Cuece hasta que la berenjena esté tierna; incorpora los garbanzos cocidos y calienta bien."}], "reference_energy_kcal": 399.51, "reference_energy_kcal_exact": "399.51", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["chickpea"]}, {"id": "side", "kind": "side", "name": {"en": "Grain accompaniment", "es": "Guarnición de cereal"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "rice_white", "quantity": 50, "unit": "g", "variety_role": "base"}], "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}], "reference_energy_kcal": 175.5, "reference_energy_kcal_exact": "175.5", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["rice"]}, {"id": "dessert", "kind": "dessert", "name": {"en": "Apple and yogurt", "es": "Manzana con yogur"}, "optional": true, "default_included": false, "ingredients": [{"ingredient_id": "apple", "quantity": 120, "unit": "g", "variety_role": "support"}, {"ingredient_id": "yogurt", "quantity": 80, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Wash and core the apple, weigh and chop; serve with the measured yogurt.", "es": "Lava la manzana y retira el corazón; pesa y corta la parte comestible y sirve con el yogur medido."}], "reference_energy_kcal": 106.8, "reference_energy_kcal_exact": "106.8", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian"], "variety_keys": []}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 575.01, "with_optional_dessert": 681.81}, "reference_energy_kcal_exact": {"without_optional_dessert": "575.01", "with_optional_dessert": "681.81"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian", "vegetarian", "vegan"], "with_optional_dessert": ["omnivore", "pescatarian", "vegetarian"]}, "ingredient_preparation": [{"ingredient_id"