insert into app_private.starter_content values('2026-11','recipe','m11','{"id": "m11", "name": {"en": "Lighter potato tortilla", "es": "Tortilla de patata con poco aceite"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 25, "components": [{"id": "main", "kind": "main", "name": {"en": "Lighter potato tortilla", "es": "Tortilla de patata con poco aceite"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "potato", "quantity": 220, "unit": "g", "variety_role": "base"}, {"ingredient_id": "egg", "quantity": 100, "unit": "g", "variety_role": "main"}, {"ingredient_id": "onion", "quantity": 80, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Slice the raw peeled potato thinly. Steam or microwave with a little water until tender; drain.", "es": "Corta la patata cruda pelada en láminas finas. Cuécela al vapor o en microondas con un poco de agua hasta que esté tierna; escurre."}, {"en": "Soften onion in the measured oil, then add potato and beaten egg. Cook gently on both sides until fully set throughout.", "es": "Rehoga la cebolla con el aceite medido; añade la patata y el huevo batido. Cocina suavemente por ambos lados hasta que esté completamente cuajada."}], "reference_energy_kcal": 384.35, "reference_energy_kcal_exact": "384.35", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian"], "variety_keys": ["egg", "potato"]}, {"id": "side", "kind": "side", "name": {"en": "Tomato and cucumber salad", "es": "Ensalada de tomate y pepino"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "tomato", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "cucumber", "quantity": 80, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_