insert into app_private.starter_content values('2026-11','recipe','m12','{"id": "m12", "name": {"en": "Spinach quinoa with almonds", "es": "Quinoa con espinacas y almendras"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 20, "components": [{"id": "main", "kind": "main", "name": {"en": "Spinach quinoa with almonds", "es": "Quinoa con espinacas y almendras"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "quinoa", "quantity": 70, "unit": "g", "variety_role": "base"}, {"ingredient_id": "spinach", "quantity": 160, "unit": "g", "variety_role": "main"}, {"ingredient_id": "tomato", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "almond", "quantity": 20, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 10, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Rinse and cook the weighed dry quinoa. Wilt spinach and garlic in the measured oil.", "es": "Lava y cuece la quinoa pesada en seco. Rehoga las espinacas y el ajo con el aceite medido."}, {"en": "Combine quinoa, spinach, chopped tomato, almonds and lemon juice; serve warm.", "es": "Combina la quinoa, las espinacas, el tomate cortado, las almendras y el zumo de limón; sirve templado."}], "reference_energy_kcal": 415.29, "reference_energy_kcal_exact": "415.29", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["quinoa", "spinach"]}, {"id": "dessert", "kind": "dessert", "name": {"en": "Berry yogurt", "es": "Yogur con frutos rojos"}, "optional": true, "default_included": false, "ingredients": [{"ingredient_id": "strawberry", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "blueberry", "quantity": 50, "unit": "g", "variety_role": "support"}, {"ingredient_id": "yogurt", "quantity": 80, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Wash and weigh the berries, slice if needed and serve with the yogurt.", "es": "Lava y pesa los frutos rojos, córtalos si hace falta y sirve con el yogur."}], "reference_energy_kcal": 95.6, "reference_energy_kcal_exact": "95.6", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian"], "variety_keys": []}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 415.29, "with_optional_dessert": 510.89}, "reference_energy_kcal_exact": {"without_optional_dessert": "415.29", "with_optional_dessert": "510.89"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian", "vegetarian", "vegan"], "with_optional_dessert": ["omnivore", "pescatarian", "vegetarian"]}, "ingredient_preparation": [{"ingredient_id": "quinoa", "mode": "separate_before_finishing", "kind": "dry_grain", "instructions": {"en": "Weigh dry, then cook with water according to the packet until tender; rinse quinoa first. Drain only if the packet method requires it. Count the original dry quantity for calories. Serve rice promptly; cool leftovers quickly, ideally within one hour, refrigerate, use within 24 hours and reheat only once.", "es": "Pesa en seco y cocina con agua según el envase hasta que esté tierno; lava antes la quinoa. Escurre solo si el método del envase lo requiere. Usa la cantidad seca inicial para calcular las calorías. Sirve el arroz enseguida; enfría las sobras rápidamente, idealmente en una hora, refrigera, consume en 24 horas y recalienta una sola vez."}}], "dietary_label_checks": {"without_optional_dessert": [], "with_optional_dessert": [{"ingredient_id": "yogurt", "for_patterns": ["vegetarian"], "status": "requir