insert into app_private.starter_content values('2026-11','recipe','m13','{"id": "m13", "name": {"en": "Roasted pepper and white bean pitta", "es": "Pita de pimiento asado y alubias blancas"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 25, "components": [{"id": "main", "kind": "main", "name": {"en": "Roasted pepper and white bean pitta", "es": "Pita de pimiento asado y alubias blancas"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "beans_white", "quantity": 60, "unit": "g", "variety_role": "main"}, {"ingredient_id": "pitta", "quantity": 70, "unit": "g", "variety_role": "base"}, {"ingredient_id": "pepper_red", "quantity": 150, "unit": "g", "variety_role": "support"}, {"ingredient_id": "rocket", "quantity": 30, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 10, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Prepare the dry beans separately. Roast pepper strips with measured oil at 200°C until tender.", "es": "Prepara aparte las alubias secas. Asa el pimiento en tiras con el aceite medido a 200 °C hasta que esté tierno."}, {"en": "Mash the cooked beans with lemon, garlic and salt. Fill the warmed pitta with the bean mixture, peppers and washed rocket.", "es": "Machaca las alubias cocidas con el limón, el ajo y la sal. Rellena la pita caliente con la mezcla, el pimiento y la rúcula lavada."}], "reference_energy_kcal": 435.59, "reference_energy_kcal_exact": "435.59", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["bread", "white_bean"]}, {"id": "dessert", "kind": "dessert", "name": {"en": "Banana cocoa yogurt", "es": "Yogur con plátano y cacao"}, "optional": true, "default_included": false, "ingredients": [{"ingredient_id": "banana", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "yogurt", "quantity": 80, "unit": "g", "variety_role": "support"}, {"ingredient_id": "cocoa", "quantity": 3, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Peel and weigh the banana. Stir cocoa into yogurt and add banana slices.", "es": "Pela y pesa el plátano. Mezcla el cacao con el yogur y añade el plátano cortado."}], "reference_energy_kcal": 135.96, "reference_energy_kcal_exact": "135.96", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian"], "variety_keys": []}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 435.59, "with_optional_dessert": 571.55}, "reference_energy_kcal_exact": {"without_optional_dessert": "435.59", "with_optional_dessert": "571.55"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian", "vegetarian", "vegan"], "with_optional_dessert": ["omnivore", "pescatarian", "vegetarian"]}, "ingredient_preparation": [{"ingredient_id": "beans_white", "mode": "separate_before_finishing", "kind": "dry_legume", "soak_minutes": 720, "additional_cook_minutes_range": [60, 120], "instructions": {"en": "Weigh dry, then soak at least 12 hours. Discard soaking water, rinse, and use plenty of fresh water. Boil vigorously for at least 10 minutes, then continue cooking until fully tender, following the packet if it requires longer. Never cook raw kidney beans only in a slow cooker. The dry weight, not the hydrated weight, is the calorie reference.", "es": "Pesa en seco y remoja al menos 12 horas. Desecha el agua de remojo, enjuaga y usa abundante agua nueva. Hierve enérgicamente al menos 10 minutos y continúa la cocción hasta que estén completamente tiernas, siguiendo el envase si exige más tiempo. Nunca cocines alubias rojas crudas solo en una olla de cocción lenta. La referencia calórica es el peso seco, no el hidratado."}}], "dietary_label_checks": {"without_optional_dessert": [{"ingredient_id": "pitta", "for_patterns": ["vegan"], "status": "requires_actual_product_label_confirmation", "requirement": {"en": "Choose a source-matching product whose label confirms the selected dietary pattern; generic nutrition data do not certify every brand.", "es": "Elige un producto que corresponda a la referencia y cuya etiqueta confirme el patrón alimentario elegido; los datos genéricos no certifican todas las marcas."}}], "with_optional_dessert": [{"ingredient_id": "pitta", "for_patterns": ["vegan"], "status": "requires_actual_product_label_confirmation", "requirement": {"en": "Choose a source-matching product whose label confirms the selected dietary pattern; generic nutrition data do not certify every brand.", "es": "Elige un producto que corresponda a la referencia y cuya etiqueta confirme el patrón alimentario elegido; los datos genéricos no certifican todas las marcas."}}, {"ingredient_id": "yogurt", "for_patterns": ["vegetarian"], "status": "requires_actual_product_label_confirmation", "requirement": {"en": "Choose a source-matching product whose label confirms the selected dietary pattern; generic nutrition data do not certify every brand.", "es": "Elige un producto que corresponda a la referencia y cuya etiqueta confirme el patrón alimentario elegido; los datos genéricos no certifican todas las marcas."}}]}, "finishing_times_exclude_soaking_and_prerequisite_cooking": true, "safety_note_ids": ["weigh_and_prepare"]}'::jsonb);
insert into app_private.starter_content values('2026-11','recipe','m14','{"id": "m14", "name": {"en": "Pea and mint barley bowl", "es": "Bol de cebada, guisantes y menta"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 20, "components": [{"id": "main", "kind": "main", "name": {"en": "Pea and mint barley bowl", "es": "Bol de cebada, guisantes y menta"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "peas", "quantity": 180, "unit": "g", "variety_role": "main"}, {"ingredient_id": "barley", "quantity": 70, "unit": "g", "variety_role": "base"}, {"ingredient_id": "spring_onion", "quantity": 40, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "mint", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 10, "unit": "g", "variety_role": "support"}, {"ingredient_id": "pumpkin_seed", "quantity": 10, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Cook the weighed dry barley. Boil frozen peas until cooked through, following the packet.", "es": "Cuece la cebada pesada en seco. Hierve los guisantes congelados hasta que estén hechos, siguiendo el envase."}, {"en": "Soften sliced spring onion in measured oil, then combine with barley, peas, lemon, mint and pumpkin seeds.", "es": "Rehoga la cebolleta cortada con el aceite medido; mezcla con la cebada, los guisantes, el limón, la menta y las pipas de calabaza."}], "reference_energy_kcal": 487.04, "reference_energy_kcal_exact": "487.04", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["barley", "pea"]}, {"id": "dessert", "kind": "dessert", "name": {"en": "Melon and mint", "es": "Melón con menta"}, "optional": true, "default_included": false, "ingredients": [{"ingredient_id": "melon", "quantity": 180, "unit": "g", "variety_role": "support"}, {"ingredient_id": "mint", "quantity": 2, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Remove peel and seeds, weigh the melon flesh and serve with washed mint.", "es": "Retira la piel y las semillas, pesa la pulpa del melón y sirve con menta lavada."}], "reference_energy_kcal": 44.06, "reference_energy_kcal_exact": "44.06", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": []}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 487.04, "with_optional_dessert": 531.1}, "reference_energy_kcal_exact": {"without_optional_dessert": "487.04", "with_optional_dessert": "531.1"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian", "vegetarian", "vegan"], "with_optional_dessert": ["omnivore", "pescatarian", "vegetarian", "vegan"]}, "ingredient_preparation": [{"ingredient_id": "barley", "mode": "separate_before_finishing", "kind": "dry_grain", "instructions": {"en": "Weigh dry, then cook with water according to the packet until tender; rinse quinoa first. Drain only if the packet method requires it. Count the original dry quantity for calories. Serve rice promptly; cool leftovers quickly, ideally within one hour, refrigerate, use within 24 hours and reheat only once.", "es": "Pesa en seco y cocina con agua según el envase hasta que esté tierno; lava antes la quinoa. Escurre solo si el método del envase lo requiere. Usa la cantidad seca inicial para calcular las calorías. Sirve el arroz enseguida; enfría las sobras rápidamente, idealmente en una hora, refrigera, consume en 24 horas y recalienta una sola vez."}}], "dietary_label_checks": {"without_optional_dessert": [], "with_optional_dessert": []}, "finishing_times_exclude_soaking_and_prerequisite_cooking": true, "safe