insert into app_private.starter_content values('2026-11','recipe','m15','{"id": "m15", "name": {"en": "Beef and pepper bulgur skillet", "es": "Sartén de ternera, pimiento y bulgur"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 25, "components": [{"id": "main", "kind": "main", "name": {"en": "Beef and pepper bulgur skillet", "es": "Sartén de ternera, pimiento y bulgur"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "beef", "quantity": 140, "unit": "g", "variety_role": "main"}, {"ingredient_id": "pepper_red", "quantity": 150, "unit": "g", "variety_role": "support"}, {"ingredient_id": "tomato_canned", "quantity": 150, "unit": "g", "variety_role": "support"}, {"ingredient_id": "onion", "quantity": 60, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "parsley", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Soften onion and pepper in measured oil. Add garlic and beef mince and break it up as it cooks.", "es": "Rehoga la cebolla y el pimiento con el aceite medido. Añade el ajo y la carne picada, separándola mientras se cocina."}, {"en": "Add tomatoes and simmer until the mince is thoroughly cooked; check the core-temperature instruction. Serve with bulgur and parsley.", "es": "Añade el tomate y cuece hasta que la carne esté completamente hecha; comprueba la indicación de temperatura interior. Sirve con bulgur y perejil."}], "reference_energy_kcal": 311.91, "reference_energy_kcal_exact": "311.91", "dietary_patterns": ["omnivore"], "variety_keys": ["beef"]}, {"id": "side", "kind": "side", "name": {"en": "Grain accompaniment", "es": "Guarnición de cereal"}, "optional": false, "defa