insert into app_private.starter_content values('2026-11','recipe','m16','{"id": "m16", "name": {"en": "Turkey oat meatballs with pasta", "es": "Albóndigas de pavo y avena con pasta"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 30, "components": [{"id": "main", "kind": "main", "name": {"en": "Turkey oat meatballs with pasta", "es": "Albóndigas de pavo y avena con pasta"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "turkey", "quantity": 140, "unit": "g", "variety_role": "main"}, {"ingredient_id": "oats", "quantity": 10, "unit": "g", "variety_role": "support"}, {"ingredient_id": "egg", "quantity": 20, "unit": "g", "variety_role": "support"}, {"ingredient_id": "tomato_canned", "quantity": 200, "unit": "g", "variety_role": "support"}, {"ingredient_id": "onion", "quantity": 60, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "basil", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Finely mince the weighed turkey light meat; mix with oats, weighed egg and half the garlic, then shape small meatballs.", "es": "Pica finamente la carne blanca de pavo pesada; mezcla con la avena, el huevo pesado y la mitad del ajo y forma albóndigas pequeñas."}, {"en": "Soften onion and remaining garlic in measured oil. Add tomatoes and meatballs, cover and simmer until cooked through; check their centres reach the specified safe temperature.", "es": "Rehoga la cebolla y el ajo restante con el aceite medido. Añade el tomate y las albóndigas, tapa y cuece hasta que estén hechas; comprueba que el centro alcance la temperatura segura indicada."}, {"en": "Serve with cooked pasta and basil.", "es": "Sir