insert into app_private.starter_content values('2026-11','recipe','m17','{"id": "m17", "name": {"en": "Lemon chicken with potatoes and broccoli", "es": "Pollo al limón con patata y brócoli"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 40, "components": [{"id": "main", "kind": "main", "name": {"en": "Lemon chicken with potatoes and broccoli", "es": "Pollo al limón con patata y brócoli"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "chicken", "quantity": 150, "unit": "g", "variety_role": "main"}, {"ingredient_id": "potato", "quantity": 220, "unit": "g", "variety_role": "base"}, {"ingredient_id": "broccoli", "quantity": 160, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 20, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "parsley", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Cut peeled potato into small cubes. Toss with half the measured oil and roast at 200°C for 15 minutes.", "es": "Corta la patata pelada en dados pequeños. Mezcla con la mitad del aceite medido y asa a 200 °C durante 15 minutos."}, {"en": "Add chicken coated with remaining oil, lemon and garlic. Roast until the potato is tender and the chicken reaches the safe core temperature; steam broccoli separately.", "es": "Añade el pollo con el aceite restante, el limón y el ajo. Asa hasta que la patata esté tierna y el pollo alcance la temperatura interior segura; cuece el brócoli al vapor aparte."}, {"en": "Serve together with parsley and the listed salt.", "es": "Sirve todo junto con el perejil y la sal indicada."}], "reference_energy_kcal": 444.11, "reference_energy_k