insert into app_private.starter_content values('2026-11','recipe','m20','{"id": "m20", "name": {"en": "Dill salmon with potatoes and green beans", "es": "Salmón al eneldo con patatas y judías verdes"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 25, "components": [{"id": "main", "kind": "main", "name": {"en": "Dill salmon with potatoes and green beans", "es": "Salmón al eneldo con patatas y judías verdes"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "salmon", "quantity": 140, "unit": "g", "variety_role": "main"}, {"ingredient_id": "potato", "quantity": 200, "unit": "g", "variety_role": "base"}, {"ingredient_id": "green_beans", "quantity": 160, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 15, "unit": "g", "variety_role": "support"}, {"ingredient_id": "dill", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Boil or steam the weighed raw potato and trimmed green beans until tender.", "es": "Hierve o cuece al vapor la patata pesada en crudo y las judías verdes limpias hasta que estén tiernas."}, {"en": "Bake salmon with measured oil, lemon and dill at 190°C until fully cooked and safely hot in the centre. Serve with the vegetables.", "es": "Hornea el salmón con el aceite medido, el limón y el eneldo a 190 °C hasta que esté completamente cocinado y a temperatura segura en el centro. Sirve con las verduras."}], "reference_energy_kcal": 534.97, "reference_energy_kcal_exact": "534.97", "dietary_patterns": ["omnivore", "pescatarian"], "variety_keys": ["potato", "salmon"]}, {"id": "dessert", "kind": "dessert", "name": {"en": "Berry yogurt", "es": "Yogur con frutos rojos"}, "optional": true, "default_included": false, "ingredients": [{