insert into app_private.starter_content values('2026-11','recipe','m21','{"id": "m21", "name": {"en": "Cod with chickpea tomato sauce", "es": "Bacalao con salsa de tomate y garbanzos"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 25, "components": [{"id": "main", "kind": "main", "name": {"en": "Cod with chickpea tomato sauce", "es": "Bacalao con salsa de tomate y garbanzos"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "cod", "quantity": 160, "unit": "g", "variety_role": "main"}, {"ingredient_id": "chickpeas", "quantity": 50, "unit": "g", "variety_role": "base"}, {"ingredient_id": "tomato_canned", "quantity": 200, "unit": "g", "variety_role": "support"}, {"ingredient_id": "spinach", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "onion", "quantity": 50, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "parsley", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Prepare the dry chickpeas separately. Soften onion and garlic in measured oil, add tomatoes and simmer 10 minutes.", "es": "Prepara aparte los garbanzos secos. Rehoga cebolla y ajo con el aceite medido, añade el tomate y cuece 10 minutos."}, {"en": "Add cooked chickpeas and nestle cod into the sauce. Cover until the fish is safely cooked through, then wilt in spinach and add parsley.", "es": "Añade los garbanzos cocidos y coloca el bacalao en la salsa. Tapa hasta que el pescado esté completamente cocinado a temperatura segura; incorpora las espinacas y el perejil."}], "reference_energy_kcal": 400.41, "reference_energy_kcal_exact": "400.41", "dietary_patterns": ["omnivore", "pescatarian"], "variety_keys": ["chickpea", "cod"]}, {"id": "dessert", "kind": "dessert", "name": {"en": "Banana cocoa yogurt", "es": "Yogur con plátano y cacao"}, "optional": true, "default_included": false, "ingredients": [{"ingredient_id": "banana", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "yogurt", "quantity": 80, "unit": "g", "variety_role": "support"}, {"ingredient_id": "cocoa", "quantity": 3, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Peel and weigh the banana. Stir cocoa into yogurt and add banana slices.", "es": "Pela y pesa el plátano. Mezcla el cacao con el yogur y añade el plátano cortado."}], "reference_energy_kcal": 135.96, "reference_energy_kcal_exact": "135.96", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian"], "variety_keys": []}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 400.41, "with_optional_dessert": 536.37}, "reference_energy_kcal_exact": {"without_optional_dessert": "400.41", "with_optional_dessert": "536.37"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian"], "with_optional_dessert": ["omnivore", "pescatarian"]}, "ingredient_preparation": [{"ingredient_id": "chickpeas", "mode": "separate_before_finishing", "kind": "dry_legume", "soak_minutes": 720, "additional_cook_minutes_range": [60, 120], "instructions": {"en": "Weigh dry, then soak at least 12 hours. Discard soaking water, rinse, and use plenty of fresh water. Boil vigorously for at least 10 minutes, then continue cooking until fully tender, following the packet if it requires longer. Never cook raw kidney beans only in a slow cooker. The dry weight, not the hydrated weight, is the calorie reference.", "es": "Pesa en seco y remoja al menos 12 horas. Desecha el agua de remojo, enjuaga y usa abundante agua nueva. Hierve enérgicamente al menos 10 minutos y continúa la cocción hasta que estén completamente tiernas, siguiendo el envase si exige más tiempo. Nunca cocines alubias rojas crudas solo en una olla de cocción lenta. La referencia calórica es el peso seco, no el hidratado."}}], "dietary_label_checks": {"without_optional_dessert": [], "with_optional_dessert": [{"ingredient_id": "yogurt", "for_patterns": ["vegetarian"], "status": "requires_actual_product_label_confirmation", "requirement": {"en": "Choose a source-matching product whose label confirms the selected dietary pattern; generic nutrition data do not certify every brand.", "es": "Elige un producto que corresponda a la referencia y cuya etiqueta confirme el patrón alimentario elegido; los datos genéricos no certifican todas las marcas."}}]}, "finishing_times_exclude_soaking_and_prerequisite_cooking": true, "safety_note_ids": ["weigh_and_prepare", "cook_thoroughly"]}'::jsonb);
insert into app_private.starter_content values('2026-11','recipe','m22','{"id": "m22", "name": {"en": "Garlic prawn rice with peas", "es": "Arroz con langostinos al ajo y guisantes"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 20, "components": [{"id": "main", "kind": "main", "name": {"en": "Garlic prawn rice with peas", "es": "Arroz con langostinos al ajo y guisantes"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "prawns", "quantity": 160, "unit": "g", "variety_role": "main"}, {"ingredient_id": "peas", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "garlic", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 15, "unit": "g", "variety_role": "support"}, {"ingredient_id": "parsley", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Cook the weighed dry rice. Boil the frozen peas following the packet and drain.", "es": "Cuece el arroz pesado en seco. Hierve los guisantes congelados siguiendo el envase y escurre."}, {"en": "Heat measured oil and garlic; add raw edible prawns and cook thoroughly to the safe core-temperature instruction. Fold through rice, peas, lemon and parsley.", "es": "Calienta el aceite medido y el ajo; añade los langostinos crudos sin partes no comestibles y cocina hasta alcanzar la temperatura interior segura indicada. Incorpora el arroz, los guisantes, el limón y el perejil."}], "reference_energy_kcal": 243.12, "reference_energy_kcal_exact": "243.12", "dietary_patterns": ["omnivore", "pescatarian"], "variety_keys": ["prawn"]}, {"id": "side", "kind": "side", "name": {"en": "Grain accompaniment", "es": "Guarnición de cereal"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "rice_white", "quantity": 70, "unit": "g", "variety_role": "base"}], "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}], "reference_energy_kcal": 245.7, "reference_energy_kcal_exact": "245.7", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["rice"]}, {"id": "dessert", "kind": "dessert", "name": {"en": "Melon and mint", "es": "Melón con menta"}, "optional": true, "default_included": false, "ingredients": [{"ingredient_id": "melon", "quantity": 180, "unit": "g", "variety_role": "support"}, {"ingredient_id": "mint", "quantity": 2, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Remove peel and seeds, weigh the melon flesh and serve with washed mint.", "es": "Retira la piel y las semillas, pesa la pulpa del melón y sirve con menta lavada."}], "reference_energy_kcal": 44.06, "reference_energy_kcal_exact": "44.06", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": []}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 488.82, "with_optional_dessert": 532.88}, "reference_energy_kcal_exact": {"without_optional_dessert": "488.82", "with_optional_dessert": "532.88"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian"], "with_optional_dessert": ["omnivore", "pescatarian"]}, "ingredient_preparation": [{"ingredient_id": "rice_white", "mode": "separate_before_finishing", "kind": "dry_grain", "instructions": {"en": "Weigh dry, then cook with water according to the packet until tender; rinse quinoa first. Drain only if the packet method requires it. Count the original dry quantity for calories. Serve rice promptly; cool leftovers quickly, ideally within one hour, refrigerate, use within 24 hours and reheat only once.", "es": "Pesa en seco y cocina con agua según el envase hasta que esté tierno; lava antes la quinoa. Escurre solo si el método del envase lo requiere. Usa la cantidad seca inicial para calcular las calorías. Sirve el arroz enseguida; enfría las sobras rápidamente, idealmente en una hora, refrigera, consume en 24 horas y recalienta una sola vez."}}], "dietary_label_checks": {"without_optional_dessert": [], "with_optional_dessert": []}, "finishing_times_exclude_soaking_and_prerequisite_cooking": true, "safety_note_ids": ["weigh_and_prepare", "cook_thoroughly", "rice_storage"]}'::jsonb);
insert into app_private.starter_content values('2026-11','recipe','m23','{"id": "m23", "name": {"en": "Tuna, tomato and lemon pasta", "es": "Pasta con atún, tomate y limón"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 12, "components": [{"id": "main", "kind": "main", "name": {"en": "Tuna, tomato and lemon pasta", "es": "Pasta con atún, tomate y limón"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "tuna", "quantity": 120, "unit": "g", "variety_role": "main"}, {"ingredient_id": "tomato", "quantity": 180, "unit": "g", "variety_role": "support"}, {"ingredient_id": "rocket", "quantity": 40, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 15, "unit": "g", "variety_role": "support"}, {"ingredient_id": "basil", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Drain and weigh tuna. Cook the weighed dry pasta, then drain.", "es": "Escurre y pesa el atún. Cuece la pasta pesada en seco y escurre."}, {"en": "Toss pasta with tuna, chopped washed tomato, rocket, measured oil, lemon and basil; serve immediately.", "es": "Mezcla la pasta con el atún, el tomate lavado y cortado, la rúcula, el aceite medido, el limón y la albahaca; sirve enseguida."}], "reference_energy_kcal": 210.4, "reference_energy_kcal_exact": "210.4", "dietary_patterns": ["omnivore", "pescatarian"], "variety_keys": ["tuna"]}, {"id": "side", "kind": "side", "name": {"en": "Grain accompaniment", "es": "Guarnición de cereal"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "pasta", "quantity": 70, "unit": "g", "variety_role": "base"}], "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}], "reference_energy_kcal": 240.1, "reference_energy_kcal_exact": "240.1", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": ["pasta"]}, {"id": "dessert", "kind": "dessert", "name": {"en": "Grapes and walnuts", "es": "Uvas con nueces"}, "optional": true, "default_included": false, "ingredients": [{"ingredient_id": "grapes", "quantity": 120, "unit": "g", "variety_role": "support"}, {"ingredient_id": "walnut", "quantity": 10, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Wash and weigh the edible grapes and serve with the measured walnut kernels.", "es": "Lava y pesa la parte comestible de las uvas y sirve con las nueces medidas."}], "reference_energy_kcal": 146.8, "reference_energy_kcal_exact": "146.8", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": []}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 450.5, "with_optional_dessert": 597.3}, "reference_energy_kcal_exact": {"without_optional_dessert": "450.5", "with_optional_dessert": "597.3"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian"], "with_optional_dessert": ["omnivore", "pescatarian"]}, "ingredient_preparation": [{"ingredient_id": "pasta", "mode": "separate_before_finishing", "kind": "dry_grain", "instructions": {"en": "Weigh dry, then cook with water according to the packet until tender; rinse quinoa first. Drain only if the packet method requires it. Count the original dry quantity for calories. Serve rice promptly; cool leftovers quickly, ideally within one hour, refrigerate, use within 24 hours and reheat only once.", "es": "Pesa en seco y cocina con agua según el envase hasta que esté tierno; lava antes la quinoa. Escurre solo si el método del envase lo requiere. Usa la cantidad seca inicial para calcular las calorías. Sirve el arroz enseguida; enfría las sobras rápidamente, idealmente en una hora, refrigera, consume en 24 horas y recalienta una sola vez."}}], "dietary_label_checks": {"without_optional_dessert": [], "with_optional_dessert": []}, "finishing_times_exclude_soaking_and_prerequisite_cooking": true, "safety_note_ids": ["weigh_and_prepare"]}'::jsonb);
insert into app_private.starter_content values('2026-11','recipe','m24','{"id": "m24", "name": {"en": "Sardine and tomato toast", "es": "Tostadas de sardinas y tomate"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 8, "finishing_cook_minutes": 3, "components": [{"id": "main", "kind": "main", "name": {"en": "Sardine and tomato toast", "es": "Tostadas de sardinas y tomate"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "sardines", "quantity": 100, "unit": "g", "variety_role": "main"}, {"ingredient_id": "bread", "quantity": 80, "unit": "g", "variety_role": "base"}, {"ingredient_id": "tomato", "quantity": 160, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 10, "unit": "g", "variety_role": "support"}, {"ingredient_id": "parsley", "quantity": 3, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Drain the sardines before weighing. Toast the bread and top with washed sliced tomato.", "es": "Escurre las sardinas antes de pesarlas. Tuesta el pan y coloca encima el tomate lavado y cortado."}, {"en": "Add sardines, lemon and parsley. The source nutrition already includes retained oil; no additional oil is listed.", "es": "Añade las sardinas, el limón y el perejil. Los valores de referencia ya incluyen el aceite retenido; no se añade aceite adicional."}], "reference_energy_kcal": 417.72, "reference_energy_kcal_exact": "417.72", "dietary_patterns": ["omnivore", "pescatarian"], "variety_keys": ["bread", "sardine"]}, {"id": "side", "kind": "side", "name": {"en": "Tomato and cucumber salad", "es": "Ensalada de tomate y pepino"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "tomato", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "cucumber", "quantity": 80, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "vinegar", "quantity": 5, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Wash and chop the vegetables. Toss with the measured oil and vinegar.", "es": "Lava y corta las verduras. Mézclalas con el aceite y el vinagre medidos."}], "reference_energy_kcal": 53.27, "reference_energy_kcal_exact": "53.27", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": []}, {"id": "dessert", "kind": "dessert", "name": {"en": "Kiwi and orange", "es": "Kiwi y naranja"}, "optional": true, "default_included": false, "ingredients": [{"ingredient_id": "kiwi", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "orange", "quantity": 100, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Peel both fruits, weigh the edible flesh, chop and combine.", "es": "Pela ambas frutas, pesa la parte comestible, corta y mezcla."}], "reference_energy_kcal": 80.0, "reference_energy_kcal_exact": "8E+1", "dietary_patterns": ["omnivore", "pescatarian", "vegetarian", "vegan"], "variety_keys": []}], "provenance": {"kind": "original_repository_content", "copied_recipe_text": false}, "review_status": "desk_validated_not_kitchen_tested", "reference_energy_kcal": {"without_optional_dessert": 470.99, "with_optional_dessert": 550.99}, "reference_energy_kcal_exact": {"without_optional_dessert": "470.99", "with_optional_dessert": "550.99"}, "dietary_patterns": {"without_optional_dessert": ["omnivore", "pescatarian"], "with_optional_dessert": ["omnivore", "pescatarian"]}, "ingredient_preparation": [], "dietary_label_checks": {"without_optional_dessert": [{"ingredient_id": "bread", "for_patterns": ["vegan"], "status": "requires_actual_product_label_confirmation", "requirement": {"en": "Choose a source-matching product whose label confirms the selected dietary pattern; generic nutrition data do not certify every brand.", "es": "Elige un producto que corresponda a la referencia y cuya etiqueta confirme el patrón alimentario