insert into app_private.starter_content values('2026-11','recipe','m25','{"id": "m25", "name": {"en": "Beef and mushroom yogurt skillet", "es": "Ternera con champiñones y yogur"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 25, "components": [{"id": "main", "kind": "main", "name": {"en": "Beef and mushroom yogurt skillet", "es": "Ternera con champiñones y yogur"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "beef", "quantity": 140, "unit": "g", "variety_role": "main"}, {"ingredient_id": "mushroom", "quantity": 180, "unit": "g", "variety_role": "support"}, {"ingredient_id": "onion", "quantity": 60, "unit": "g", "variety_role": "support"}, {"ingredient_id": "yogurt", "quantity": 80, "unit": "g", "variety_role": "support"}, {"ingredient_id": "mustard", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 5, "unit": "g", "variety_role": "support"}, {"ingredient_id": "parsley", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Soften onion and mushrooms in measured oil. Add extra-lean beef mince and cook thoroughly, breaking it apart.", "es": "Rehoga la cebolla y los champiñones con el aceite medido. Añade la ternera picada extramagra y cocina completamente, separándola."}, {"en": "Check the safe core temperature, then remove from the heat and stir in yogurt and mustard without boiling. Serve with rice and parsley.", "es": "Comprueba la temperatura interior segura; retira del fuego e incorpora el yogur y la mostaza sin hervir. Sirve con arroz y perejil."}], "reference_energy_kcal": 314.12, "reference_energy_kcal_exact": "314.12", "dietary_patterns": ["omnivore"], "variety_keys": ["beef"]}, {"id": "side", "kind": "side", "name": {"en": "Grain accompaniment", "es": "Guarnición de cereal"}, "optional": false, "defa