insert into app_private.starter_content values('2026-11','recipe','m29','{"id": "m29", "name": {"en": "Salmon and tomato rice bowl", "es": "Bol de arroz con salmón y tomate"}, "meal_types": ["lunch", "dinner"], "reference_servings": 1, "active_prep_minutes": 10, "finishing_cook_minutes": 25, "components": [{"id": "main", "kind": "main", "name": {"en": "Salmon and tomato rice bowl", "es": "Bol de arroz con salmón y tomate"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "salmon", "quantity": 140, "unit": "g", "variety_role": "main"}, {"ingredient_id": "tomato", "quantity": 150, "unit": "g", "variety_role": "support"}, {"ingredient_id": "cucumber", "quantity": 100, "unit": "g", "variety_role": "support"}, {"ingredient_id": "olive_oil", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "lemon_juice", "quantity": 15, "unit": "g", "variety_role": "support"}, {"ingredient_id": "dill", "quantity": 3, "unit": "g", "variety_role": "support"}, {"ingredient_id": "salt", "quantity": 1, "unit": "g", "variety_role": "support"}], "instructions": [{"en": "Cook the weighed dry rice. Bake salmon with measured oil at 190°C until safely cooked through.", "es": "Cuece el arroz pesado en seco. Hornea el salmón con el aceite medido a 190 °C hasta que esté completamente cocinado a temperatura segura."}, {"en": "Combine warm rice with salmon, washed chopped tomato and cucumber, lemon and dill. Serve immediately.", "es": "Combina el arroz templado con el salmón, el tomate y el pepino lavados y cortados, el limón y el eneldo. Sirve enseguida."}], "reference_energy_kcal": 367.57, "reference_energy_kcal_exact": "367.57", "dietary_patterns": ["omnivore", "pescatarian"], "variety_keys": ["salmon"]}, {"id": "side", "kind": "side", "name": {"en": "Grain accompaniment", "es": "Guarnición de cereal"}, "optional": false, "default_included": true, "ingredients": [{"ingredient_id": "rice_brown", "quantity": 60, "unit": "g", "variety_role": "base"}