-- Pinned shared starter release; existing household rows remain private overrides.
begin;
alter table public.household add column starter_release text not null default '2026-11';
create table app_private.starter_content (
 release text not null, kind text not null check(kind in ('ingredient','recipe','substitution')),
 id text not null, data jsonb not null, primary key(release,kind,id)
);
alter table app_private.starter_content enable row level security;
create policy starter_read on app_private.starter_content for select to authenticated,week_menu_executor using (app_private.is_member());
revoke all on app_private.starter_content from public,anon,authenticated,week_menu_executor;
grant select on app_private.starter_content to authenticated,week_menu_executor;
create view app_private.resolved_food_items with (security_invoker=true) as
 select p.* from public.food_items p
 union all select s.id,s.data,1 as revision,false as archived,app_private.current_household() as household_id from app_private.starter_content s
 where s.kind='ingredient' and s.release=(select starter_release from public.household where id)
 and not exists(select 1 from public.food_items p where p.id=s.id);
grant select on app_private.resolved_food_items to authenticated,week_menu_executor;
create view app_private.resolved_saved_recipes with (security_invoker=true) as
 select p.* from public.saved_recipes p
 union all select s.id,s.data,1 as revision,false as archived,app_private.current_household() as household_id from app_private.starter_content s
 where s.kind='recipe' and s.release=(select starter_release from public.household where id)
 and not exists(select 1 from public.saved_recipes p where p.id=s.id);
grant select on app_private.resolved_saved_recipes to authenticated,week_menu_executor;
create view app_private.resolved_substitution_rules with (security_invoker=true) as
 select p.* from public.substitution_rules p
 union all select s.id,s.data,app_private.current_household() as household_id from app_private.starter_content s
 where s.kind='substitution' and s.release=(select starter_release from public.household where id)
 and not exists(select 1 from public.substitution_rules p where p.id=s.id);
grant select on app_private.resolved_substitution_rules to authenticated,week_menu_executor;
-- A generated shopping ingredient may now belong to the common release.
-- Replace the private-table-only FK with the same scoped existence check over resolution.
alter table public.shopping_items drop constraint shopping_items_household_id_ingredient_id_fkey;
create function app_private.check_shopping_ingredient() returns trigger language plpgsql set search_path='' as $$begin
 if new.ingredient_id is not null and not exists(select 1 from app_private.resolved_food_items f where f.household_id=new.household_id and f.id=new.ingredient_id) then
  raise exception 'invalid_shopping_ingredient' using errcode='23503';
 end if;
 return new;
end$$;
revoke all on function app_private.check_shopping_ingredient() from public,anon,authenticated;
create trigger shopping_ingredient_reference before insert or update on public.shopping_items for each row execute function app_private.check_shopping_ingredient();
-- Historical shopping references also resolve the immutable common revision.
create view app_private.resolved_food_references with (security_invoker=true) as
 select p.* from app_private.food_reference_versions p
 union all select s.id,1,s.data->>'state',coalesce(s.data->>'quantity_basis','edible_reference_weight'),coalesce(s.data->>'shopping_policy','include'),app_private.current_household()
 from app_private.starter_content s
 where s.kind='ingredient' and s.release=(select starter_release from public.household where id)
 and not exists(select 1 from app_private.food_reference_versions p where p.ingredient_id=s.id and p.revision=1);
grant select on app_private.resolved_food_references to authenticated,week_menu_executor;
-- Redirect catalogue reads while retaining writes to household override tables.
do $$declare f record; definition text;begin
 for f in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='app_private' and p.prokind='f' loop
  definition:=pg_get_functiondef(f.oid);
  if definition ~ 'public\.(food_items|saved_recipes|substitution_rules)' or definition like '%app_private.food_reference_versions%' then
   definition:=replace(definition,'app_private.food_reference_versions','app_private.resolved_food_references');
   definition:=replace(definition,'insert into app_private.resolved_food_references','insert into app_private.food_reference_versions');
   definition:=replace(replace(replace(definition,'public.food_items','app_private.resolved_food_items'),'public.saved_recipes','app_private.resolved_saved_recipes'),'public.substitution_rules','app_private.resolved_substitution_rules');
   definition:=replace(replace(replace(definition,'insert into app_private.resolved_food_items','insert into public.food_items'),'insert into app_private.resolved_saved_recipes','insert into public.saved_recipes'),'insert into app_private.resolved_substitution_rules','insert into public.substitution_rules');
   execute definition;
  end if;
 end loop;
end$$;
commit;
